<nav class="campaign-tabs" aria-label="Template views"><?php foreach(['built-in'=>'MOED templates','saved'=>'Saved','recent'=>'Recently sent']as$key=>$label): ?><a href="<?= $h($url(['view'=>'templates','tab'=>$key])) ?>"<?= $tab===$key?' aria-current="page"':'' ?>><?= $label ?></a><?php endforeach; ?></nav>
<div class="template-toolbar"><label class="campaign-search"><span class="sr-only">Search templates</span><input type="search" placeholder="Search <?= $tab==='saved'?'saved':'MOED' ?> templates" data-template-search></label><?php if($tab==='saved'): ?><label>Folder <select data-template-folder><option value="">All</option><?php foreach(array_unique(array_column($templates,'folder'))as$folder)if($folder!==''): ?><option><?= $h($folder) ?></option><?php endif; ?></select></label><?php endif; ?><label>Template type <select data-template-type><option value="">All</option><option value="visual">Drag-and-drop</option><option value="code">Code your own</option></select></label><label>Sort by <select data-template-sort><option value="newest">Newest</option><option value="name">Alphabetical</option><option value="oldest">Oldest</option></select></label><button data-template-all-filters>All filters</button><button data-template-layout="grid" aria-label="Grid view" aria-pressed="true">▦</button><button data-template-layout="list" aria-label="List view" aria-pressed="false">☰</button></div>
<?php if($tab==='built-in'): ?><div class="template-categories" aria-label="Template categories"><?php foreach(['All','Announce','Invite to an event','Newsletter','Sell products','Sell services','Thank you','Transactional','Welcome']as$category): ?><button data-template-category="<?= $h($category) ?>" aria-pressed="<?= $category==='All'?'true':'false' ?>"><?= $category ?></button><?php endforeach; ?></div><h2>All templates</h2><?php endif; ?>
<div class="template-gallery" id="template-gallery">
<?php $library=[];if($tab==='built-in')foreach($starters as$key=>$starter)$library[]=['key'=>$key,'name'=>$starter['name'],'category'=>$starter['category'],'design'=>$starter['design'],'folder'=>'','updated_at'=>'','version'=>0];elseif($tab==='saved')foreach($templates as$t)$library[]=$t+['design'=>audienceJson($t['design_json']),'category'=>'All'];else foreach($recentDesigns as$r){$d=audienceJson($r['draft_json']);if(isset($d['design']))$library[]=$r+['design'=>$d['design'],'category'=>'All','folder'=>''];} ?>
<?php foreach($library as$entry): ?><article class="template-card" data-template-name="<?= $h(mb_strtolower($entry['name'])) ?>" data-template-category-value="<?= $h($entry['category']) ?>" data-template-folder-value="<?= $h($entry['folder']) ?>" data-template-date="<?= $h($entry['updated_at']) ?>" data-template-mode="<?= $h($entry['design']['mode']??'visual') ?>"><div class="template-thumbnail"><iframe title="Preview <?= $h($entry['name']) ?>" sandbox="" loading="lazy" data-email-preview="<?= $h(audienceDesignPreviewHtml($entry['design'],contentSecurityPolicyNonce())) ?>"></iframe></div><div class="template-card-info"><h3><?= $h($entry['name']) ?></h3><p><?= $h($entry['folder']?:($entry['category']==='All'?'Marketing':$entry['category'])) ?></p><?php if($entry['updated_at']): ?><small>Last edited <?= $h(gmdate('M j, Y',strtotime($entry['updated_at']))) ?></small><?php endif; ?></div><div class="template-card-actions">
<?php if($canManage&&$tab==='built-in'): ?><form method="post"><?= $csrf ?><input type="hidden" name="action" value="template_create"><input type="hidden" name="starter" value="<?= $h($entry['key']) ?>"><button class="primary">Use template</button></form>
<?php elseif($canManage&&$tab==='saved'): ?><a class="audience-button" href="<?= $h($url(['view'=>'designer','kind'=>'template','id'=>$entry['id']])) ?>">Edit</a><form method="post"><?= $csrf ?><?php audienceInputs(['action'=>'template_operation','id'=>$entry['id'],'version'=>$entry['version'],'operation'=>'campaign']); ?><button>Create email</button></form><details class="audience-menu"><summary aria-label="Actions for <?= $h($entry['name']) ?>">⌄</summary><div><a href="<?= $h($url(['view'=>'templates','download'=>$entry['id']])) ?>">Export as HTML</a><?php foreach(['rename'=>'Rename','folder'=>'Move to folder','replicate'=>'Replicate','delete'=>'Delete']as$op=>$label): ?><button type="button" data-template-operation="<?= $op ?>" data-template-record="<?= $h(json_encode(array_intersect_key($entry,array_flip(['id','name','version','folder'])))) ?>"><?= $label ?></button><?php endforeach; ?></div></details>
<?php elseif($tab==='recent'): ?><?php if($canManage): ?><form method="post"><?= $csrf ?><?php audienceInputs(['action'=>'template_from_campaign','id'=>$entry['id']]); ?><button>Use design</button></form><?php endif; ?><a class="audience-button" href="<?= $h($url(['view'=>'campaign','id'=>$entry['id']])) ?>">View campaign</a><?php endif; ?></div></article><?php endforeach; ?>
</div><div id="template-pagination" class="template-pagination"></div><p class="template-empty" <?= $library?'hidden':'' ?> data-template-empty>No templates found.<?= $tab==='saved'?' Save a design as a template to reuse it here.':'' ?></p>
<?php if($canManage): ?><dialog id="template-operation" aria-labelledby="template-operation-title"><h2 id="template-operation-title">Rename template</h2><form method="post"><?= $csrf ?><?php audienceInputs(['action'=>'template_operation','id'=>0,'version'=>0,'operation'=>'rename']); ?><label data-template-input-label>Template name<input name="name" maxlength="100"></label><p data-template-delete-note hidden>This removes the template from your library. Campaigns made from it keep their designs.</p><div class="dialog-actions"><button type="button" data-design-close>Cancel</button><button class="primary">Save</button></div></form></dialog><?php endif; ?>

<?php if($canManage): ?>
<dialog id="template-import-dialog" class="designer-wide-dialog" <?= ($_POST['action']??'')==='template_import'&&$error!==''?'data-reopen-dialog':'' ?> aria-labelledby="template-import-title"><header><h2 id="template-import-title">Code your own</h2><button type="button" data-design-close aria-label="Close import">×</button></header><p>Custom-coded templates use the code editor and named editable regions. Their original source is retained.</p><div class="designer-subtabs"><button data-import-tab="paste" aria-pressed="true">Paste in code</button><button data-import-tab="html">Import HTML</button><button data-import-tab="zip">Import ZIP</button></div><form method="post" enctype="multipart/form-data"><?= $csrf ?><input type="hidden" name="action" value="template_import"><label>Template name<input name="name" maxlength="100" required value="<?= $h(is_string($_POST['name']??null)?$_POST['name']:'') ?>"></label><label data-import-code>HTML source<textarea name="code" rows="15" maxlength="1000000" spellcheck="false"><?= $h(is_string($_POST['code']??null)?$_POST['code']:'') ?></textarea></label><label data-import-file hidden>Template file<input type="file" name="template_file" accept=".html,.htm,.zip"></label><p data-import-help class="audience-help">Paste your HTML. Add mc:edit="region_name" to create editable content areas.</p><div class="dialog-actions"><button type="button" data-design-close>Cancel</button><button class="primary">Import</button></div></form></dialog>
<dialog id="template-legacy-dialog" aria-labelledby="template-legacy-title"><h2 id="template-legacy-title">Create a legacy template</h2><form method="post"><?= $csrf ?><input type="hidden" name="action" value="template_legacy"><label>Template name<input name="name" maxlength="100" required></label><label>Layout<select name="columns"><option value="1">1 column</option><option value="2">2 columns</option><option value="3">3 columns</option></select></label><p class="audience-help">Start with a table-based layout and editable header, body, and footer regions.</p><div class="dialog-actions"><button type="button" data-design-close>Cancel</button><button class="primary">Create</button></div></form></dialog>
<?php endif; ?>

